              Navigator.of(dialogContext).pop(false); 
            },
            child: const Text('Nein'),
          ),
          const SizedBox(width: 10),
          // Button "Ja" - Schließt den Dialog mit 'true' ab
          ElevatedButton(
            onPressed: () {
              Navigator.of(dialogContext).pop(true);
            },
            child: const Text('Ja'),
          ),
        ],
      );
    },
  );

  // Hier kann nun die Logik basierend auf dem Ergebnis ausgeführt werden.
  if (result == true) {
