  } else if (result == false) {
    print("Verarbeitung: Fahrt fortgesetzt.");
    // Nichts tun, da der Nutzer die Aktion abgebrochen hat.
  } else {
    // Das Dialog wurde durch Tippen außerhalb geschlossen (Dismissed).
    print("Verarbeitung: Dialog wurde ohne Wahl geschlossen.");
  }
