/// Zeigt den Bestätigungsdialog "Fahrt beenden?" an.
/// Dieser Dialog sollte von einem Aufruf innerhalb eines State-Kontextes erfolgen.
void showEndTripDialog({
  required BuildContext context,
  required Function() onConfirmTripEnded, // Handler für 'Ja' (Beenden)
  required Function() onCancelTripEnd,    // Handler für 'Nein' (Abbrechen)
}) {
  showDialog(
    context: context,
    builder: (BuildContext dialogContext) {
      return AlertDialog(
        title: const Text('Fahrt beenden?'),
        content: const Text("Sind Sie sicher, dass Sie die Fahrt beenden möchten?"),
        actions: <Widget>[
          TextButton(
            onPressed: () {
              // Exekutiere den Cancel-Handler und schließe das Dialog
              onCancelTripEnd(); 
              Navigator.of(dialogContext).pop();
            },
            child: const Text("Nein", style: TextStyle(color: Colors.grey)),
          ),
          TextButton(
            onPressed: () {
              // Exekutiere den Confirm-Handler und schließe das Dialog
              onConfirmTripEnded(); 
              Navigator.of(dialogContext).pop();
            },
            child: const Text("Ja", style: TextStyle(color: Colors.red)),
          ),
        ],
      );
    },
  );
}

