/// Zeigt einen Bestätigungsdialog "Fahrt beenden?" an.
/// 
/// Die Callback-Funktionen werden ausgeführt, sobald der Benutzer auf den jeweiligen Button klickt.
///
/// [context]: Der BuildContext des Elternwidgets. Wird benötigt, um den Dialog zu zeigen.
/// [onConfirmed]: Handler, der bei Klick auf "Ja" (Bestätigung) aufgerufen wird.
/// [onCancelled]: Handler, der bei Klick auf "Nein" (Abbruch/Verneinung) aufgerufen wird.
Future<void> showTripEndConfirmationDialog({
  required BuildContext context,
  required Function() onConfirmed,
  required Function() onCancelled,
}) async {
  await showDialog(
    context: context,
    builder: (BuildContext dialogContext) {
      return AlertDialog(
        title: const Text("Fahrt beenden?"),
        content: const Text(
            "Sind Sie sicher, dass Sie die aktuelle Fahrt beenden möchten? Diese Aktion kann nicht rückgängig gemacht werden."),
        actions: <Widget>[
          // Button Nein (Abbrechen)
          TextButton(
            onPressed: () {
              Navigator.of(dialogContext).pop(); // Dialog schließen
              onCancelled(); // Handler aufrufen
            },
            child: const Text("Nein"),
          ),
          // Button Ja (Bestätigen)
          ElevatedButton( // Kann auch als FilledButton oder OutlinedButton gestaltet werden
            onPressed: () {
              Navigator.of(dialogContext).pop(); // Dialog schließen
              onConfirmed(); // Handler aufrufen
            },
            style: ElevatedButton.styleFrom(
                backgroundColor: Colors.red, 
                foregroundColor: Colors.white),
            child: const Text("Ja"),
          ),
        ],
      );
    },
  );
}

