/// Die Funktionalität wird über Callbacks abstrahiert, sodass die aufrufende
/// Widget (`car_home_screen`) die spezifische Logik für Ja/Nein bereitstellen kann.
Future<void> showTripEndingConfirmationDialog({
  required BuildContext context,
  required VoidCallback onConfirm, // Wird aufgerufen, wenn der Benutzer 'Ja' tippt (Fahrt beenden)
  required VoidCallback onCancel,  // Wird aufgerufen, wenn der Benutzer 'Nein' tippt oder abbricht
}) async {
  await showDialog(
    context: context,
    builder: (BuildContext dialogContext) {
      return AlertDialog(
        title: const Text('Fahrt beenden?'),
        content: const Text('Möchten Sie die aktuelle Fahrt tatsächlich beenden und die Daten speichern?'),
        actions: <Widget>[
          // Button für Nein (Abbrechen/Verkürzen)
          TextButton(
            onPressed: () {
              Navigator.of(dialogContext).pop(); // Dialog schließen
              onCancel(); // Callback für Abbrechen ausführen
            },
            child: const Text('Nein'),
          ),

          // Button für Ja (Bestätigung)
          ElevatedButton(
            style: ElevatedButton.elevation(0),
            onPressed: () {
              Navigator.of(dialogContext).pop(); // Dialog schließen
              onConfirm(); // Callback für Bestätigen ausführen
            },
            child: const Text('Ja', style: TextStyle(fontSize: 18)),
          ),
        ],
      );
    },
  );
}

